#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

#define int long long

long long base[1000005];
long long digits_arr[1000005];
long long flags[1000005];
long long temp_arr[1000005];
long long best=1e18;

void compute()
{
    for (int i=0; i<18; i++)
    {
        digits_arr[i]=temp_arr[i];
    }
    for (int i=0; i<17; i++)
    {
        if (flags[i]>0)
        {
            digits_arr[i+1]++;
            digits_arr[i]-=10;
            digits_arr[0]--;
        }
    }
    if (digits_arr[0]<-6)
    {
        digits_arr[0]+=11;
        digits_arr[1]--;
    }
    if (digits_arr[0]>6)
    {
        digits_arr[0]-=11;
        digits_arr[1]++;
    }
    long long total_score=0;
    for (int i=0; i<18; i++)
    {
        total_score+=abs(digits_arr[i])*(i+1);
    }
    best=min(best,total_score);
}

void backtrack(int idx)
{
    if (idx>=17)
    {
        compute();
        return;
    }
    for (int val=0; val<=1; val++)
    {
        flags[idx]=val;
        backtrack(idx+1);
    }
}

int main()
{
    int n;
    cin>>n;
    base[0]=1;
    for (int i=1; i<18; i++)
    {
        base[i]=base[i-1]*10+1;
    }
    int current=n;
    int position=17;
    while (current>0)
    {
        temp_arr[position]=current/base[position];
        current%=base[position];
        position--;
    }
    backtrack(0);
    cout<<best;
}
